# ----------------- TESHIS (kalici, sifre korumali tani sayfasi) -----------------
# Panel [teshis] loglarini buraya POST eder; /teshis sayfasi (sifre ile) gosterir. Konsol yerine
# buradan bakilir. Sifre: env TESHIS_SIFRE varsa o (duz), yoksa asagidaki HASH (repo'da yalniz hash).
TESHIS_SIFRE_HASH = "1f8de283b8564e9db20bfe63215bf16b9117801c3712f32c7c21690fa0856b18"
_teshis_log = []   # [{t, lvl, msg}] — son 800 kayit (RAM; docker restart'ta sifirlanir)
_TESHIS_MAX = 800

def _teshis_ok(k):
    try:
        k = k or ""
        env = os.environ.get("TESHIS_SIFRE")
        if env:
            return hmac.compare_digest(str(k), str(env))
        return hmac.compare_digest(hashlib.sha256(k.encode("utf-8")).hexdigest(), TESHIS_SIFRE_HASH)
    except Exception:
        return False

def _teshis_ekle(lvl, msg):
    try:
        _teshis_log.append({"t": time.time(), "lvl": (lvl or "info")[:10], "msg": str(msg)[:2000]})
        if len(_teshis_log) > _TESHIS_MAX:
            del _teshis_log[:len(_teshis_log) - _TESHIS_MAX]
    except Exception:
        pass

# --- B (havuz birlesmesi): editor "+" ile eklenen manuel bolumler ARTIK gercek sunucu
# havuzu ogesi olur (link alaninda sentetik "xmanual://<uid>" anahtariyla). Bu bayrak kapaliyken
# tum birlesme davranisi devre disi kalir (auto_start eski kosulsuz temizlige doner, detect_platform
# "manual" dondurmez) -> istemci x_unify_manual bayragiyla birlikte temiz, veri-guvenli geri alma.
X_UNIFY_MANUAL = (os.environ.get("X_UNIFY_MANUAL", "1") != "0")

def is_manual_link(link):
    # Editor-manuel bolum sentetik anahtari. normalize_link_key/x_temizle_link bunu OLDUGU GIBI
    # gecirir (ig/fb/tt/yt/x.com host'u degil), overlay/gorsel/havuz kimligi TEK anahtara duser.
    return bool(link) and str(link).lower().startswith("xmanual://")

def get_client_id():
    try:
        c_id = request.args.get("client_id")
        if not c_id:
            c_id = request.form.get("client_id")
        if not c_id and request.is_json:
            try:
                c_id = request.json.get("client_id")
            except:
                pass
        return c_id or request.remote_addr
    except:
        # Fallback if request context is not active
        return "default"

def get_client_pool():
    c_id = get_client_id()
    if c_id not in client_pools:
        client_pools[c_id] = []
    return client_pools[c_id]

def get_client_job():
    c_id = get_client_id()
    if c_id not in client_jobs:
        client_jobs[c_id] = {
            "job_id": None,
            "scrape_mode": None,
            "tweet_urls": [],
            "results": [],
            "results_count": 0,
            "total_count": 0,
            "status": "idle", # idle, running, completed
            "last_extension_heartbeat": 0.0,
            "start_time": 0.0,
            "end_time": 0.0
        }
    return client_jobs[c_id]

