# [ILERLEME DONMA FIX] mammoth'u Web Worker'da calistir -> agir .docx ayristirmasi ANA-THREAD'i
# bloke etmez -> ilerleme cubugu donmaz, UI kilitlenmez. Worker /x-mammoth.js'i importScripts eder
# (ayni origin; mammoth DOM gerektirmez, worker'da calisir -- canli test edildi).
MAMMOTH_WORKER_JS = r'''importScripts('/x-mammoth.js');
self.onmessage = function (e) {
  var d = e.data || {}, id = d.id, buf = d.buf;
  if (!buf) { self.postMessage({ id: id, ok: false, error: 'bos arraybuffer' }); return; }
  try {
    self.mammoth.convertToHtml({ arrayBuffer: buf }, { ignoreEmptyParagraphs: false })
      .then(function (r) { self.postMessage({ id: id, ok: true, html: (r && r.value) || '' }); })
      .catch(function (err) { self.postMessage({ id: id, ok: false, error: String(err && err.message || err) }); });
  } catch (err) { self.postMessage({ id: id, ok: false, error: String(err && err.message || err) }); }
};
'''

@app.route('/x-mammoth-worker.js', methods=['GET'])
def x_mammoth_worker_js():
    return _js_yanit(MAMMOTH_WORKER_JS)

