TESHIS_PAGE = r'''<!doctype html>
<html lang="tr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>GörüntüX Teşhis</title>
<style>
 body{margin:0;background:#0e141f;color:#e7e9ea;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:13px;}
 header{position:sticky;top:0;background:#111a2b;padding:10px 14px;border-bottom:1px solid #22304a;display:flex;gap:8px;align-items:center;flex-wrap:wrap;z-index:5;}
 header b{font-size:14px;color:#fff;}
 button{background:#1d9bf0;color:#fff;border:none;border-radius:6px;padding:6px 12px;font:inherit;cursor:pointer;}
 button:hover{filter:brightness(1.12);}
 button.sec{background:#2a3a55;}
 button:disabled{opacity:.5;cursor:default;}
 #durum{color:#8899a6;margin-left:auto;font-size:12px;}
 .ozet{padding:8px 14px;background:#0d1626;border-bottom:1px solid #182236;display:flex;gap:18px;flex-wrap:wrap;align-items:center;font-size:12.5px;color:#aeb9c7;}
 .ozet b{color:#e7e9ea;}
 .meter{display:inline-block;width:120px;height:7px;background:#22304a;border-radius:4px;overflow:hidden;vertical-align:middle;margin:0 4px;}
 .meter>i{display:block;height:100%;background:#1d9bf0;}
 .ozet .uyari{color:#ff8a8a;}
 .rapor-ac{color:#1d9bf0;cursor:pointer;text-decoration:underline;}
 #raporlar{padding:4px 14px 10px;border-bottom:1px solid #182236;display:none;}
 table{width:100%;border-collapse:collapse;font-size:12px;}
 th,td{text-align:left;padding:4px 8px;border-bottom:1px solid #182236;}
 th{color:#5a6b85;font-weight:400;}
 td .big{color:#f0a35e;font-weight:700;}
 .olc{background:#2a3a55;padding:2px 8px;font-size:11px;}
 #liste{padding-bottom:60px;}
 .satir{padding:4px 14px;border-bottom:1px solid #182236;white-space:pre-wrap;word-break:break-all;}
 .satir .t{color:#5a6b85;margin-right:10px;}
 .satir.err{color:#ff8a8a;}
 .satir.op{color:#7ee6a8;}
 .bos{padding:20px 14px;color:#8899a6;}
 #giris{min-height:72vh;display:flex;align-items:center;justify-content:center;}
 #giris .box{background:#111a2b;border:1px solid #22304a;border-radius:10px;padding:22px 20px;width:300px;max-width:90vw;}
 #giris h2{margin:0 0 4px;font-size:15px;color:#fff;}
 #giris p{margin:0 0 14px;color:#8899a6;font-size:12px;}
 #giris input{width:100%;background:#0e141f;border:1px solid #22304a;color:#e7e9ea;border-radius:6px;padding:9px 11px;font:inherit;margin-bottom:10px;}
 #giris .hata{color:#ff8a8a;font-size:12px;margin-top:8px;display:none;}
 .kopya-ok{background:#113a22 !important;color:#7ee6a8 !important;}
</style></head>
<body>
<div id="giris"><div class="box">
  <h2>GörüntüX Teşhis</h2>
  <p>Şifre korumalı tanı paneli.</p>
  <input id="sifre" type="password" placeholder="Teşhis şifresi" autocomplete="off">
  <button id="giris-btn" style="width:100%;">Giriş</button>
  <div class="hata" id="giris-hata">Şifre yanlış.</div>
</div></div>
<div id="panel" style="display:none;">
 <header>
  <b>GörüntüX Teşhis</b>
  <button id="yenile">Yenile</button>
  <button class="sec" id="otobtn">Oto: AÇIK</button>
  <button class="sec" id="kopbtn">Kopyala</button>
  <button class="sec" id="indbtn">İndir</button>
  <button class="sec" id="havbtn">Havuz</button>
  <button class="sec" id="tembtn">Temizle</button>
  <button class="sec" id="cikbtn">Çıkış</button>
  <span id="durum">bekleniyor...</span>
 </header>
 <div class="ozet" id="ozet"></div>
 <div id="raporlar"></div>
 <div id="havuz" style="display:none;padding:4px 14px 10px;border-bottom:1px solid #182236;"></div>
 <div id="liste"></div>
</div>
<script>
var K=''; try{ K=localStorage.getItem('x_teshis_k')||''; }catch(e){}
var oto=true, sonVeri=null, sonDepo=null, sonMetas=[], _poll=null;
function $(id){ return document.getElementById(id); }
function esc(s){ return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
function fmtB(n){ if(!(n>0)) return '0 B'; var u=['B','KB','MB','GB']; var i=Math.floor(Math.log(n)/Math.log(1024)); i=Math.min(i,3); return (n/Math.pow(1024,i)).toFixed(i?1:0)+' '+u[i]; }
function fmtT(t){ try{ return new Date(t*1000).toLocaleTimeString('tr-TR'); }catch(e){ return ''; } }
async function veri(){ try{ var r=await fetch('/api/teshis/data',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({k:K}),cache:'no-store'}); if(r.status===403) return {ok:false}; return await r.json(); }catch(e){ return {ok:false,hata:String(e&&e.message||e)}; } }
async function giris(){ K=$('sifre').value||''; var d=await veri(); if(d&&d.ok){ try{ localStorage.setItem('x_teshis_k',K); }catch(e){} $('giris').style.display='none'; $('panel').style.display='block'; $('giris-hata').style.display='none'; basla(); } else { $('giris-hata').style.display='block'; } }
function cikis(){ try{ localStorage.removeItem('x_teshis_k'); }catch(e){} K=''; if(_poll) clearInterval(_poll); $('panel').style.display='none'; $('giris').style.display='flex'; }
function logClass(l){ if(l.lvl==='error') return 'err'; var m=l.msg||''; if(m.indexOf('[openRapor]')>=0||m.indexOf('[merge]')>=0) return 'op'; return ''; }
function renderLog(logs){ logs=logs||[]; var lst=$('liste'); if(!logs.length){ lst.innerHTML='<div class="bos">Henüz log yok. Bir rapor açmayı/birleştirmeyi dene; aşamalar burada belirir.</div>'; return; } lst.innerHTML=logs.map(function(l){ return '<div class="satir '+logClass(l)+'"><span class="t">'+esc(fmtT(l.t))+'</span>'+esc(l.msg||'')+'</div>'; }).join(''); if(oto) window.scrollTo(0, document.body.scrollHeight); }
async function depolama(){ try{ if(navigator.storage&&navigator.storage.estimate){ var e=await navigator.storage.estimate(); sonDepo={u:e.usage||0,q:e.quota||0}; } else { sonDepo=null; } }catch(e){ sonDepo=null; } }
function ozetCiz(){
  var h=''; if(sonDepo){ var p=sonDepo.q?Math.min(100,Math.round(sonDepo.u/sonDepo.q*100)):0; h+='<span>Depolama: <b>'+fmtB(sonDepo.u)+'</b> / '+fmtB(sonDepo.q)+' <span class="meter"><i style="width:'+p+'%;'+(p>85?'background:#ff8a8a;':'')+'"></i></span> <b'+(p>85?' class="uyari"':'')+'>%'+p+'</b>'+(p>85?' (dolmak üzere!)':'')+'</span>'; } else { h+='<span>Depolama: <b>—</b></span>'; }
  var toplam=sonMetas.reduce(function(a,m){ return a+(m.itemCount||0); },0);
  h+='<span>Raporlar: <b>'+sonMetas.length+'</b> ('+toplam+' öğe) <span class="rapor-ac" id="rap-ac">listele ▾</span></span>';
  $('ozet').innerHTML=h;
  var ra=$('rap-ac'); if(ra) ra.addEventListener('click', function(){ var r=$('raporlar'); var acik=r.style.display!=='none'; r.style.display=acik?'none':'block'; ra.textContent=acik?'listele ▾':'gizle ▴'; if(!acik) raporlarCiz(); });
}
function idbMetas(){ return new Promise(function(resolve){ try{ var rq=indexedDB.open('goruntux_saved_reports'); rq.onsuccess=function(){ var db=rq.result; try{ var g=db.transaction('meta','readonly').objectStore('meta').getAll(); g.onsuccess=function(){ resolve(g.result||[]); db.close(); }; g.onerror=function(){ resolve([]); db.close(); }; }catch(e){ resolve([]); try{db.close();}catch(_){} } }; rq.onerror=function(){ resolve([]); }; }catch(e){ resolve([]); } }); }
function idbDataBoyut(id){ return new Promise(function(resolve){ try{ var rq=indexedDB.open('goruntux_saved_reports'); rq.onsuccess=function(){ var db=rq.result; try{ var g=db.transaction('data','readonly').objectStore('data').get(id); g.onsuccess=function(){ var d=g.result||{}; var imgN=d.images?Object.keys(d.images).length:0; var blobN=(d.blob&&d.blob.size)||0; var imgB=0; try{ for(var k in d.images){ if(d.images[k]&&d.images[k].dataUrl) imgB+=d.images[k].dataUrl.length; } }catch(e){} resolve({imgN:imgN,blobN:blobN,imgB:imgB}); db.close(); }; g.onerror=function(){ resolve(null); db.close(); }; }catch(e){ resolve(null); try{db.close();}catch(_){} } }; rq.onerror=function(){ resolve(null); }; }catch(e){ resolve(null); } }); }
// [TEŞHİS] Kayıtlı raporun NIHAI item'ları (snapItems = editör overlay sonrası group_override + h2_override).
function idbDataItems(id){ return new Promise(function(resolve){ try{ var rq=indexedDB.open('goruntux_saved_reports'); rq.onsuccess=function(){ var db=rq.result; try{ var g=db.transaction('data','readonly').objectStore('data').get(id); g.onsuccess=function(){ var d=g.result||{}; resolve(d.items||[]); db.close(); }; g.onerror=function(){ resolve([]); db.close(); }; }catch(e){ resolve([]); try{db.close();}catch(_){} } }; rq.onerror=function(){ resolve([]); }; }catch(e){ resolve([]); } }); }
async function raporDok(id){
  var box=$('havuz'); box.style.display='block'; box.innerHTML='<div class="bos">Rapor ogeleri okunuyor...</div>';
  var its=await idbDataItems(id);
  if(!its.length){ box.innerHTML='<div class="bos">Bu raporda oge yok (ya da snapItems bos).</div>'; return; }
  var h='<div style="color:#8899a6;font-size:12px;margin:2px 0 6px;">Kayitli rapor NIHAI ogeleri ('+its.length+') &mdash; editor overlay SONRASI group_override + h2_override. Ayni sayfa webshot = AYNI group_override + h2_override YOK olmali.</div>';
  h+='<table><thead><tr><th>#</th><th>Baslik</th><th>group_override</th><th>h2_override</th><th>normalize</th></tr></thead><tbody>';
  h+=its.map(function(it,i){ var go=it.group_override||''; var h2=(it.h2_override!=null)?('"'+it.h2_override+'"'):'(yok)'; var h2bos=(it.h2_override!=null && String(it.h2_override)===''); return '<tr><td>'+(i+1)+'</td><td>'+esc(it.title||'(bos)')+'</td><td'+(go?'':' style="color:#ff8a8a;"')+'>'+esc(go||'(BOS)')+'</td><td'+(h2bos?' style="color:#ff8a8a;"':'')+'>'+esc(h2)+'</td><td style="color:#8899a6;word-break:break-all;">'+esc(hvNormKey(it.link))+'</td></tr>'; }).join('');
  h+='</tbody></table>';
  box.innerHTML=h;
  // [KOPYALANABİLİR] dök özetini sunucu log'una da yaz -> Kopyala ile metin olarak alınır.
  try{ var sum=its.map(function(it,i){ var h2=(it.h2_override!=null)?('"'+it.h2_override+'"'):'(yok)'; return '#'+(i+1)+' title='+(it.title||'(bos)')+' go='+(it.group_override||'(BOS)')+' h2ov='+h2; }).join('  ||  '); fetch('/api/teshis/log',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({msg:'[dok] '+its.length+' oge -> '+sum, lvl:'info'})}); }catch(e){}
}
function raporlarCiz(){
  var metas=sonMetas.slice().sort(function(a,b){ return (b.itemCount||0)-(a.itemCount||0); });
  if(!metas.length){ $('raporlar').innerHTML='<div class="bos">Kayıtlı rapor yok.</div>'; return; }
  var h='<table><thead><tr><th>Ad</th><th>Öğe</th><th>Tarih</th><th>Boyut</th></tr></thead><tbody>';
  h+=metas.map(function(m){ var big=(m.itemCount||0)>=150; var t=''; try{ t=new Date(m.updatedAt||0).toLocaleDateString('tr-TR'); }catch(e){} return '<tr><td>'+esc(m.name||'(adsız)')+'</td><td>'+(big?'<span class="big">'+(m.itemCount||0)+'</span>':(m.itemCount||0))+'</td><td>'+esc(t)+'</td><td><button class="olc" data-id="'+esc(m.id)+'">ölç</button> <button class="olc dok" data-id="'+esc(m.id)+'">dök</button> <span id="bz-'+esc(m.id)+'"></span></td></tr>'; }).join('');
  h+='</tbody></table><div class="bos" style="padding:6px 0 0;">150+ öğe = büyük rapor (turuncu). "ölç" = görsel/blob boyutu. "dök" = o raporun NIHAI öğelerini (group_override + h2_override) Havuz alanına döker (gruplama teşhisi).</div>';
  $('raporlar').innerHTML=h;
  Array.prototype.forEach.call(document.querySelectorAll('.olc:not(.dok)'), function(b){ b.addEventListener('click', async function(){ var id=b.getAttribute('data-id'); var sp=$('bz-'+id); if(sp) sp.textContent='okunuyor...'; b.disabled=true; var r=await idbDataBoyut(id); if(sp) sp.textContent=r?(r.imgN+' görsel ~'+fmtB(r.imgB)+(r.blobN?' + blob '+fmtB(r.blobN):'')):'okunamadı'; b.disabled=false; }); });
  Array.prototype.forEach.call(document.querySelectorAll('.dok'), function(b){ b.addEventListener('click', function(){ raporDok(b.getAttribute('data-id')); }); });
}
function metinUret(){
  var L=['GörüntüX Teşhis — '+new Date().toLocaleString('tr-TR')];
  if(sonDepo){ var p=sonDepo.q?Math.round(sonDepo.u/sonDepo.q*100):0; L.push('Depolama: '+fmtB(sonDepo.u)+' / '+fmtB(sonDepo.q)+' (%'+p+')'); }
  L.push('Raporlar: '+sonMetas.length);
  sonMetas.slice().sort(function(a,b){ return (b.itemCount||0)-(a.itemCount||0); }).forEach(function(m){ L.push('  - '+(m.name||'(adsız)')+' : '+(m.itemCount||0)+' öğe'); });
  L.push('--- LOG ---');
  (sonVeri&&sonVeri.logs||[]).forEach(function(l){ L.push((fmtT(l.t)||'')+' '+(l.lvl==='error'?'[HATA] ':'')+(l.msg||'')); });
  return L.join('\n');
}
async function kopyala(){
  var txt=metinUret(), btn=$('kopbtn');
  try{ await navigator.clipboard.writeText(txt); }catch(e){ try{ var ta=document.createElement('textarea'); ta.value=txt; ta.style.position='fixed'; ta.style.opacity='0'; document.body.appendChild(ta); ta.select(); document.execCommand('copy'); ta.remove(); }catch(_){} }
  var eski=btn.textContent; btn.textContent='Kopyalandı ✓'; btn.classList.add('kopya-ok'); setTimeout(function(){ btn.textContent=eski; btn.classList.remove('kopya-ok'); },1400);
}
function indir(){ try{ var txt=metinUret(); var b=new Blob([txt],{type:'text/plain'}); var u=URL.createObjectURL(b); var a=document.createElement('a'); a.href=u; a.download='goruntux-teshis-'+Date.now()+'.txt'; document.body.appendChild(a); a.click(); a.remove(); setTimeout(function(){ URL.revokeObjectURL(u); },1500); }catch(e){} }
async function tur(){ var d=await veri(); if(d&&d.ok){ sonVeri=d; renderLog(d.logs); $('durum').textContent=(d.logs?d.logs.length:0)+' satır — '+new Date().toLocaleTimeString('tr-TR'); } else if(d&&!d.ok){ cikis(); } }
async function basla(){ await depolama(); sonMetas=await idbMetas(); ozetCiz(); await tur(); if(_poll) clearInterval(_poll); _poll=setInterval(tur,1500); }
// [HAVUZ TEŞHİS] Bu tarayıcının havuz öğelerini göster (webshot gruplama + link teşhisi).
// client_id localStorage'tan (panel ile aynı origin) -> /api/status manuel_list. AYNI sayfadan
// webshot SS = AYNI grup anahtarı + AYNI normalize kök olmalı; değilse gruplama/ezme sorunu görünür.
function hvDecodeU(link){ try{ var s=String(link||''); if(s.toLowerCase().indexOf('xmanual://')===0){ var i=s.indexOf('?u='); if(i!==-1) return decodeURIComponent(s.slice(i+3)); } }catch(e){} return ''; }
function hvNormKey(link){ var s=String(link||'').split('#')[0].split('?')[0].trim().toLowerCase(); s=s.replace(/\/embed$/,''); if(s.length>1 && s.charAt(s.length-1)==='/') s=s.slice(0,-1); return s; }
// [GÖRSEL TEŞHİS] Yerel görsel IndexedDB (goruntux_local_images/images) ANAHTARLARI -> havuz öğesinin görseli
// gerçekten IndexedDB'de mi (kalıcı mı) yoksa kayıp mı, kesin görmek için.
function idbLocalImageKeys(){ return new Promise(function(resolve){ try{ var rq=indexedDB.open('goruntux_local_images'); rq.onsuccess=function(){ var db=rq.result; try{ if(!db.objectStoreNames.contains('images')){ resolve({}); db.close(); return; } var g=db.transaction('images','readonly').objectStore('images').getAllKeys(); g.onsuccess=function(){ var m={}; (g.result||[]).forEach(function(k){ m[k]=1; }); resolve(m); db.close(); }; g.onerror=function(){ resolve({}); db.close(); }; }catch(e){ resolve({}); try{db.close();}catch(_){} } }; rq.onerror=function(){ resolve({}); }; }catch(e){ resolve({}); } }); }
async function havuzGetir(){
  var box=$('havuz'); box.style.display='block'; box.innerHTML='<div class="bos">Havuz + görsel okunuyor...</div>';
  var cid=''; try{ cid=localStorage.getItem('x_client_id')||''; }catch(e){}
  var url='/api/status'+(cid?('?client_id='+encodeURIComponent(cid)):'');
  var items=[];
  try{ var r=await fetch(url,{cache:'no-store'}); var d=await r.json(); items=(d&&d.manuel_list)||[]; }catch(e){ box.innerHTML='<div class="bos">Havuz okunamadi: '+esc(String(e&&e.message||e))+'</div>'; return; }
  var idb={}; try{ idb=await idbLocalImageKeys(); }catch(e){}
  var idbN=Object.keys(idb).length;
  if(!items.length){ box.innerHTML='<div class="bos">Havuz bos (client_id='+esc(cid||'?')+'). IndexedDB yerel görsel sayısı: '+idbN+'.</div>'; return; }
  var eksik=0; items.forEach(function(it){ if(!idb[hvNormKey(it.link)]) eksik++; });
  var h='<div style="font-size:12px;margin:2px 0 6px;color:#8899a6;">Havuz: <b style="color:#e7e9ea;">'+items.length+'</b> oge · IndexedDB yerel görsel: <b style="color:#e7e9ea;">'+idbN+'</b> · IDB görseli <b'+(eksik?' style="color:#ff8a8a;"':' style="color:#7ee6a8;"')+'>EKSİK: '+eksik+'</b> (client_id='+esc(cid||'?')+')<br>YOK = havuzda öğe var ama görseli IndexedDB,de yok (KAYIP). </div>';
  h+='<table><thead><tr><th>#</th><th>Baslik</th><th>grup</th><th>normalize anahtar (IDB key)</th><th>IDB görsel</th><th>Srv</th><th>Gercek URL(?u=)</th></tr></thead><tbody>';
  h+=items.map(function(it){ var go=it.group||''; var idbVar=!!idb[hvNormKey(it.link)]; var srv=!!it.has_image; return '<tr><td>'+it.index+'</td><td>'+esc(it.title||'(bos)')+'</td><td'+(go?'':' style="color:#ff8a8a;"')+'>'+esc(go||'(BOS)')+'</td><td style="color:#8899a6;word-break:break-all;">'+esc(hvNormKey(it.link))+'</td><td'+(idbVar?' style="color:#7ee6a8;"':' style="color:#ff8a8a;font-weight:700;"')+'>'+(idbVar?'VAR':'YOK ✖')+'</td><td style="color:'+(srv?'#f0a35e':'#5a6b85')+';">'+(srv?'VAR':'-')+'</td><td style="color:#7ee6a8;word-break:break-all;">'+esc(hvDecodeU(it.link))+'</td></tr>'; }).join('');
  h+='</tbody></table>';
  box.innerHTML=h;
  try{ fetch('/api/teshis/log',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({msg:'[havuz] '+items.length+' oge | IndexedDB gorsel='+idbN+' | IDB-EKSIK='+eksik, lvl:(eksik?'error':'info')})}); }catch(e){}
}
$('havbtn').addEventListener('click', havuzGetir);
$('giris-btn').addEventListener('click', giris);
$('sifre').addEventListener('keydown', function(e){ if(e.key==='Enter') giris(); });
$('yenile').addEventListener('click', basla);
$('otobtn').addEventListener('click', function(){ oto=!oto; $('otobtn').textContent='Oto: '+(oto?'AÇIK':'KAPALI'); });
$('kopbtn').addEventListener('click', kopyala);
$('indbtn').addEventListener('click', indir);
$('tembtn').addEventListener('click', async function(){ try{ await fetch('/api/teshis/clear',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({k:K})}); }catch(e){} tur(); });
$('cikbtn').addEventListener('click', cikis);
if(K){ (async function(){ var d=await veri(); if(d&&d.ok){ $('giris').style.display='none'; $('panel').style.display='block'; basla(); } })(); }
</script>
</body></html>'''

# [Faz 2.5] /pdfeditor KALDIRILDI: PDF metin duzenleme birlesik Rapor Editorune tasindi
# (window.XPdfMetin motoru + _gdKur 'metinduz' araci). /vendor + pdf.js + /pdfjs KALDI
# (rapor PDF ciktisi + Cihazdan PDF ingest + XPdfMetin bunlari kullanir). IndexedDB 'goruntux_pdfed' artik yazilmaz.

@app.route('/teshis', methods=['GET'])
def teshis_page():
    return Response(TESHIS_PAGE, mimetype='text/html; charset=utf-8')

@app.route('/api/teshis/log', methods=['POST'])
def teshis_log_ekle():
    try:
        d = request.json or {}
        _teshis_ekle(d.get('lvl'), d.get('msg'))
    except Exception:
        pass
    return jsonify({"ok": True})

@app.route('/api/teshis/data', methods=['POST'])
def teshis_data():
    d = request.json or {}
    if not _teshis_ok(d.get('k')):
        return jsonify({"ok": False}), 403
    return jsonify({"ok": True, "logs": _teshis_log[-400:], "app_build": UYGULAMA_SURUMU, "now": time.time()})

@app.route('/api/teshis/clear', methods=['POST'])
def teshis_clear():
    d = request.json or {}
    if not _teshis_ok(d.get('k')):
        return jsonify({"ok": False}), 403
    try:
        _teshis_log.clear()
    except Exception:
        pass
    return jsonify({"ok": True})

# ----------------- MAIN RUNNER -----------------
# v3.78: TEK PORT (3011). Eskiden ayni app 3011 (panel) + 3012 (eklenti API) diye IKI portta
# calisiyordu; ayrim islevsel degil GELENEKti (her iki port da tum route'lari sunuyordu).
# Kullanici karari: sunucu her iki portu SUNMASIN. Eklenti de artik API'yi panelin portundan
# (3011) cagiriyor -> hem panel hem eklenti isi TEK PORTTA. 3012 tamamen kaldirildi.
if __name__ == '__main__':
    print("GörüntüX 3011 portunda başlatılıyor (tek port: panel + eklenti API)...", flush=True)
    try:
        app.run(host='0.0.0.0', port=3011, debug=False, threaded=True)
    except KeyboardInterrupt:
        print("Sunucu kapatılıyor...")
